// Progressive enhancement only. All content (hours, drinks, texts, both languages)
// is already in the HTML generated by build.py. This file adds: theme, mobile menu
// (focus moves in, page behind is inert), "open now" chips, next/live fixture label,
// nav scroll-spy, ticker pause button, drink tabs, lightbox, map-on-click, scroll reveal.
(() => {
    document.documentElement.classList.add('js');

    const $ = (s, r = document) => r.querySelector(s);
    const $$ = (s, r = document) => [...r.querySelectorAll(s)];
    const store = {
        get: k => { try { return localStorage.getItem(k); } catch { return null; } },
        set: (k, v) => { try { localStorage.setItem(k, v); } catch { /* ignore */ } }
    };

    // UI strings, opening hours and map URL are provided by build.py in #ui-data
    let ui = {};
    try { ui = JSON.parse($('#ui-data').textContent); } catch { /* use defaults */ }
    const S = ui.strings || {};
    const HOURS = ui.hours || [];

    // ---------- Theme (system default, manual override remembered) ----------
    const darkMq = window.matchMedia('(prefers-color-scheme: dark)');
    const reduceMq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const isDark = () => (document.documentElement.dataset.theme || (darkMq.matches ? 'dark' : 'light')) === 'dark';
    // Browser UI colour follows the active palette (css/palette.css or a theme file): the static
    // <meta name="theme-color"> tags in the HTML are only the no-JS fallback.
    function syncThemeColor() {
        const metas = $$('meta[name="theme-color"]');
        if (!metas.length) return;
        const bg = getComputedStyle(document.body).backgroundColor;
        metas.slice(1).forEach(m => m.remove());
        metas[0].removeAttribute('media');
        metas[0].setAttribute('content', bg);
    }
    function renderTheme() {
        syncThemeColor();
        const btn = $('#themeBtn');
        if (!btn) return;
        // U+FE0E asks for the text (monochrome) glyph, never a colour emoji
        btn.textContent = isDark() ? '☀︎' : '☾︎';
        btn.setAttribute('aria-label', isDark() ? S.themeLight : S.themeDark);
    }
    $('#themeBtn')?.addEventListener('click', () => {
        const next = isDark() ? 'light' : 'dark';
        document.documentElement.dataset.theme = next;
        store.set('theme', next);
        renderTheme();
    });
    darkMq.addEventListener('change', renderTheme);

    // ---------- Mobile menu ----------
    // While the overlay is open, everything outside the header (skip link, main, footer, quick bar)
    // is inert, so Tab only reaches the menu links and the header controls that stay visible above it.
    // Focus moves to the first menu link on open and back to the menu button on close.
    const nav = $('#nav'), menuBtn = $('#menuBtn');
    const siteHeader = nav ? nav.closest('header') : null;
    let menuOpen = false;
    function setPageInert(on) {
        [...document.body.children].forEach(el => {
            if (el === siteHeader || el.tagName === 'SCRIPT' || el.tagName === 'DIALOG') return;
            el.inert = on;
        });
    }
    function focusFirstLink() {
        const first = $('a', nav);
        if (!first || !menuOpen) return;
        // The CSS shows the overlay without a visibility transition on open, so it is visible now.
        // Safety net: if a stylesheet still keeps it hidden, wait for the transition to finish.
        if (getComputedStyle(nav).visibility !== 'visible') {
            nav.addEventListener('transitionend', focusFirstLink, { once: true });
            return;
        }
        first.focus({ preventScroll: true });
    }
    function setMenu(open, { restoreFocus = false } = {}) {
        if (!nav || !menuBtn) return;
        if (open === menuOpen) return;
        menuOpen = open;
        nav.classList.toggle('open', open);
        menuBtn.setAttribute('aria-expanded', String(open));
        menuBtn.setAttribute('aria-label', open ? S.menuClose : S.menuOpen);
        document.body.style.overflow = open ? 'hidden' : '';
        setPageInert(open);
        if (open) requestAnimationFrame(focusFirstLink);
        else if (restoreFocus) menuBtn.focus();
    }
    if (menuBtn) menuBtn.addEventListener('click', () => setMenu(!menuOpen));
    if (nav) nav.addEventListener('click', e => { if (e.target.closest('a')) setMenu(false); });
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && menuOpen) setMenu(false, { restoreFocus: true }); });
    // Same breakpoint as the desktop nav in css/style.css
    window.matchMedia('(min-width: 1200px)').addEventListener('change', e => { if (e.matches) setMenu(false); });

    // ---------- Header shadow + nav scroll-spy ----------
    // The link whose section crosses the 40% line of the viewport gets aria-current="location".
    const header = $('.site-header');
    const spyLinks = $$('.nav a[href^="#"]')
        .map(a => [a, document.getElementById(a.hash.slice(1))])
        .filter(([, section]) => section);
    let spyCurrent = null;
    function spy() {
        if (!spyLinks.length) return;
        const line = window.innerHeight * 0.4;
        let cur = null;
        for (const [a, section] of spyLinks) {
            const r = section.getBoundingClientRect();
            if (r.top <= line && r.bottom > line) cur = a;
        }
        const atBottom = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 4;
        if (atBottom) cur = spyLinks[spyLinks.length - 1][0];
        if (cur === spyCurrent) return;
        spyCurrent = cur;
        spyLinks.forEach(([a]) => (a === cur ? a.setAttribute('aria-current', 'location') : a.removeAttribute('aria-current')));
    }
    let ticking = false;
    const onScroll = () => {
        if (header) header.classList.toggle('scrolled', window.scrollY > 10);
        if (ticking) return;
        ticking = true;
        requestAnimationFrame(() => { ticking = false; spy(); });
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    onScroll();

    // ---------- "Open now" badge + highlight today (hours table is static HTML) ----------
    const pad = n => String(n).padStart(2, '0');
    const fmt = h => { h = h % 24; return pad(Math.floor(h)) + ':' + pad(Math.round((h % 1) * 60)); };
    function isOpen(now) {
        const day = now.getDay(), h = now.getHours() + now.getMinutes() / 60;
        const today = HOURS[day];
        if (today && h >= today[0] && h < today[1]) return today[1];
        const prev = HOURS[(day + 6) % 7];
        if (prev && prev[1] > 24 && h < prev[1] - 24) return prev[1] - 24;
        return false;
    }
    // Every [data-status] element (hero chip and the one in the hours block) shows the same state.
    function renderStatus() {
        const chips = $$('[data-status]');
        if (!chips.length || !HOURS.length) return;
        const now = new Date();
        $$('#hours tr').forEach(tr => tr.classList.toggle('today', Number(tr.dataset.d) === now.getDay()));
        const close = isOpen(now);
        const text = close ? `${S.open} · ${S.until} ${fmt(close)}` : S.closed;
        chips.forEach(chip => {
            chip.classList.toggle('open', Boolean(close));
            chip.classList.toggle('closed', !close);
            if (chip.textContent !== text) chip.textContent = text;
        });
    }
    renderStatus();
    setInterval(renderStatus, 60000);

    // ---------- Fixtures: mark the live or the next match (rows carry data-kickoff) ----------
    // A match counts as live from kick-off for 2 h 15 min. The label is text, not colour alone.
    const LIVE_MS = 135 * 60000;
    function renderFixtureState() {
        const rows = $$('[data-kickoff]');
        if (!rows.length) return;
        const now = Date.now();
        let live = null, next = null;
        for (const row of rows) {
            const t = Date.parse(row.dataset.kickoff);
            if (Number.isNaN(t)) continue;
            if (!live && t <= now && now < t + LIVE_MS) live = row;
            if (!next && t > now) next = row;
        }
        const pick = live || next;
        rows.forEach(row => {
            const label = $('[data-state]', row);
            const state = row === pick ? (live ? 'live' : 'next') : '';
            row.classList.toggle('is-live', state === 'live');
            row.classList.toggle('is-next', state === 'next');
            if (label) label.textContent = state === 'live' ? (S.stateLive || 'Live') : state === 'next' ? (S.stateNext || 'Next') : '';
        });
    }
    renderFixtureState();
    setInterval(renderFixtureState, 60000);

    // ---------- Ticker: moving content needs a pause control (WCAG 2.2.2) ----------
    const ticker = $('.ticker');
    if (ticker && !reduceMq.matches) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'ticker-toggle';
        const label = () => (ticker.classList.contains('is-paused') ? S.tickerPlay : S.tickerPause) || 'Pause';
        btn.setAttribute('aria-label', label());
        btn.addEventListener('click', () => {
            ticker.classList.toggle('is-paused');
            btn.setAttribute('aria-label', label());
        });
        ticker.append(btn);
    }

    // ---------- Drink tabs (all categories are already in the HTML) ----------
    const tabsEl = $('#drinkTabs'), menu = $('#drinks-menu');
    if (tabsEl && menu) {
        const tabs = $$('.drink-tab', tabsEl), panels = $$('.drink-panel', menu);
        tabsEl.hidden = false;
        menu.classList.add('tabs-on');
        panels.forEach(p => p.setAttribute('role', 'tabpanel'));
        const select = (tab, focus) => {
            tabs.forEach(b => {
                const on = b === tab;
                b.setAttribute('aria-selected', String(on));
                b.tabIndex = on ? 0 : -1;
            });
            panels.forEach(p => { p.hidden = p.id !== tab.getAttribute('aria-controls'); });
            if (focus) tab.focus();
        };
        tabs.forEach(b => b.addEventListener('click', () => select(b)));
        tabsEl.addEventListener('keydown', e => {
            if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
            const i = tabs.indexOf(document.activeElement);
            if (i < 0) return;
            select(tabs[(i + (e.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length], true);
        });
        select(tabs[0]);
    }

    // ---------- Lightbox ----------
    const lb = $('#lightbox'), lbImg = $('#lbImg'), items = $$('.gallery-item');
    if (lb) {
        let idx = 0;
        const reduceMotion = reduceMq;
        function show(i, dir = 0) {
            idx = (i + items.length) % items.length;
            const img = $('img', items[idx]);
            lbImg.src = img.currentSrc || img.src;
            lbImg.alt = img.alt;
            // Editorial design: a plain, short cross-fade (no slide)
            if (dir && !reduceMotion.matches && lbImg.animate) lbImg.animate(
                [{ opacity: 0 }, { opacity: 1 }], { duration: 160, easing: 'ease-out' });
        }
        items.forEach((b, i) => b.addEventListener('click', () => { show(i); lb.showModal(); }));
        $('#lbClose').addEventListener('click', () => lb.close());
        $('#lbPrev').addEventListener('click', () => show(idx - 1, -1));
        $('#lbNext').addEventListener('click', () => show(idx + 1, 1));
        lb.addEventListener('click', e => { if (e.target === lb) lb.close(); });
        lb.addEventListener('keydown', e => {
            if (e.key === 'ArrowLeft') show(idx - 1, -1);
            if (e.key === 'ArrowRight') show(idx + 1, 1);
        });
        let touchX = null;
        lb.addEventListener('touchstart', e => { touchX = e.changedTouches[0].clientX; }, { passive: true });
        lb.addEventListener('touchend', e => {
            if (touchX === null) return;
            const dx = e.changedTouches[0].clientX - touchX;
            if (Math.abs(dx) > 50) show(dx < 0 ? idx + 1 : idx - 1, dx < 0 ? 1 : -1);
            touchX = null;
        });
    }

    // ---------- Map (loads only after click, for GDPR) ----------
    const mapBtn = $('#mapBtn');
    if (mapBtn) mapBtn.addEventListener('click', () => {
        const iframe = document.createElement('iframe');
        iframe.src = ui.mapUrl;
        iframe.title = S.mapTitle || 'OpenStreetMap';
        iframe.loading = 'lazy';
        iframe.referrerPolicy = 'no-referrer';
        $('#map').replaceChildren(iframe);
    });

    // ---------- Footer year ----------
    const year = $('#year');
    if (year) year.textContent = new Date().getFullYear();

    // ---------- Scroll reveal ----------
    const reveals = $$('.reveal');
    if ('IntersectionObserver' in window && !reduceMq.matches) {
        const io = new IntersectionObserver(entries => entries.forEach(en => {
            if (en.isIntersecting) { en.target.classList.add('visible'); io.unobserve(en.target); }
        }), { threshold: 0.15 });
        reveals.forEach(el => io.observe(el));
    } else {
        reveals.forEach(el => el.classList.add('visible'));
    }

    renderTheme();
})();
